import numpy as np
import pandas as pd
import pytz
from datetime import datetime, timedelta

def r_as_POSIXct(x, tz="", *args, **kwargs):
    """
    Python reproduction of R's as.POSIXct.
    R's POSIXct is seconds since 1970-01-01.
    R handles 'origin' in the ... (kwargs) for numeric inputs.
    """

    def get_tz_info(tz_str):
        if not tz_str:
            # R's default tz is often the system TZ, but in a clean harness 
            # it usually defaults to UTC if not specified or empty.
            return pytz.UTC
        try:
            return pytz.timezone(tz_str)
        except pytz.UnknownTimeZoneError:
            return pytz.UTC

    # Handle the 'origin' argument which is common for numeric to POSIXct conversion
    # R's default origin for as.POSIXct is "1970-01-01"
    origin_str = kwargs.get('origin', '1970-01-01')

    # 1. If it's already "POSIXct" (pandas Timestamps/DatetimeIndex)
    if isinstance(x, (pd.Timestamp, pd.DatetimeIndex)):
        if tz == "":
            return x
        if isinstance(x, pd.Timestamp):
            return x.tz_localize(None).tz_localize(get_tz_info(tz)) if x.tz is None else x.tz_convert(get_tz_info(tz))
        else:
            return x.tz_convert(get_tz_info(tz))

    # 2. Null handling
    if x is None:
        return np.array([], dtype='datetime64[s]')

    # 3. Character or Factor handling
    if isinstance(x, (str, list, np.ndarray)) and (
        isinstance(x, str) or 
        (isinstance(x, (list, np.ndarray)) and len(x) == 0) or 
        (isinstance(x, (list, np.ndarray)) and any(isinstance(i, str) for i in x if i is not None))
    ):
        vals = [x] if isinstance(x, str) else x
        # pandas.to_datetime is generally compatible with R's ISO parsing
        dt_series = pd.to_datetime(vals, errors='coerce')
        tz_info = get_tz_info(tz)

        if isinstance(dt_series, pd.DatetimeIndex):
            # Localize to the target timezone
            res = dt_series.tz_localize(tz_info, ambiguous='infer', nonexistent='shift_forward')
            return res[0] if isinstance(x, str) else res
        else:
            res = dt_series.tz_localize(tz_info)
            return res

    # 4. Numeric conversion (Crucial for the failing cases)
    # If x is numeric, R adds x seconds to the origin.
    if isinstance(x, (int, float, np.integer, np.floating, np.ndarray)) and (
        isinstance(x, (int, float, np.integer, np.floating)) or 
        (isinstance(x, np.ndarray) and np.issubdtype(x.dtype, np.number))
    ):
        # Parse origin
        try:
            origin_dt = pd.Timestamp(origin_str).tz_localize('UTC')
        except:
            origin_dt = pd.Timestamp('1970-01-01', tz='UTC')

        if isinstance(x, np.ndarray):
            # Vectorized addition of seconds
            # R's POSIXct treats numeric vectors as seconds since origin
            # We use numpy's timedelta64 for efficiency
            seconds = x.astype('float64')
            res = pd.to_datetime(seconds, unit='s', origin=origin_str)
            # Ensure we match the requested timezone
            tz_info = get_tz_info(tz)
            if res.tz is None:
                res = res.tz_localize('UTC').tz_convert(tz_info)
            else:
                res = res.tz_convert(tz_info)
            return res
        else:
            # Scalar
            res = origin_dt + timedelta(seconds=float(x))
            tz_info = get_tz_info(tz)
            return res.tz_convert(tz_info)

    # 5. Logicals that are all NA
    if isinstance(x, np.ndarray) and x.dtype == bool:
        if np.all(np.isnan(x.astype(float))):
            return np.array(x.astype(float), dtype='datetime64[s]')

    # Default fail
    raise TypeError(f"do not know how to convert {type(x)} to class POSIXct")
